import React, { useState } from 'react';
import { createBooking } from '../utils/api';

const BookingForm = () => {
  const [userId, setUserId] = useState('');
  const [parkingSlotId, setParkingSlotId] = useState('');
  const [vehicleNumber, setVehicleNumber] = useState('');
  const [startTime, setStartTime] = useState('');
  const [endTime, setEndTime] = useState('');
  const [message, setMessage] = useState('');

  const handleSubmit = async (e) => {
  e.preventDefault();

  const formatToIso = (datetime) => {
    return datetime + ':00'; // Add seconds to match "yyyy-MM-ddTHH:mm:ss"
  };

  const bookingPayload = {
    vehicleNumber,
    startTime: formatToIso(startTime),
    endTime: formatToIso(endTime)
  };

  try {
    await createBooking(bookingPayload, userId, parkingSlotId);
    setMessage('✅ Booking successful!');
  } catch (error) {
    console.error('Booking error:', error);
    setMessage('❌ Error creating booking.');
  }
};

  return (
    <div>
      <h2>Book a Parking Slot</h2>
      <form onSubmit={handleSubmit}>
        <div>
          <label>User ID:</label>
          <input type="number" value={userId} onChange={(e) => setUserId(e.target.value)} required />
        </div>
        <div>
          <label>Parking Slot ID:</label>
          <input type="number" value={parkingSlotId} onChange={(e) => setParkingSlotId(e.target.value)} required />
        </div>
        <div>
          <label>Vehicle Number:</label>
          <input type="text" value={vehicleNumber} onChange={(e) => setVehicleNumber(e.target.value)} required />
        </div>
        <div>
          <label>Start Time:</label>
          <input
            type="datetime-local"
            value={startTime}
            onChange={(e) => setStartTime(e.target.value)}
            required
          />
        </div>
        <div>
          <label>End Time:</label>
          <input
            type="datetime-local"
            value={endTime}
            onChange={(e) => setEndTime(e.target.value)}
            required
          />
        </div>
        <button type="submit">Book Slot</button>
      </form>
      <p>{message}</p>
    </div>
  );
};

export default BookingForm;
